namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public int TotalRating { get; set; }
    public int RatingCount { get; set; }

    public double AverageRating => RatingCount > 0 ? (double)TotalRating / RatingCount : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Basil, Olive oil, Salt", Steps = "1. Preheat oven to 475°F.\n2. Stretch dough into a circle.\n3. Spread crushed tomatoes.\n4. Add torn mozzarella.\n5. Bake 10-12 minutes.\n6. Top with fresh basil and olive oil." },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook pasta in salted water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, stir in egg mixture.\n6. Serve immediately with extra pecorino." },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Ginger, Garlic, Onion", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, ginger, and garlic.\n4. Add tomato sauce and garam masala.\n5. Simmer 15 minutes, add cream.\n6. Add chicken pieces, cook 5 more minutes." },
        new Recipe { Id = 4, Title = "Vegetable Biryani", Category = "Indian", Ingredients = "Basmati rice, Mixed vegetables, Yogurt, Saffron, Fried onions, Mint, Cilantro, Biryani masala", Steps = "1. Soak rice 30 minutes, parboil.\n2. Cook vegetables with spices.\n3. Layer rice and vegetables in a pot.\n4. Add saffron milk and fried onions.\n5. Seal and cook on low heat 25 minutes.\n6. Garnish with mint and cilantro." },
        new Recipe { Id = 5, Title = "Tacos al Pastor", Category = "Mexican", Ingredients = "Pork shoulder, Pineapple, Dried chiles, Achiote paste, Corn tortillas, Onion, Cilantro, Lime", Steps = "1. Blend chiles and achiote into a marinade.\n2. Marinate sliced pork overnight.\n3. Grill pork with pineapple slices.\n4. Chop pork and pineapple finely.\n5. Warm tortillas.\n6. Assemble with onion, cilantro, and lime." },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Cilantro, Red onion, Jalapeño, Tomato, Salt", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Stir in lime juice and salt.\n4. Fold in diced onion, tomato, jalapeño.\n5. Add chopped cilantro.\n6. Serve immediately with tortilla chips." },
        new Recipe { Id = 7, Title = "Miso Ramen", Category = "Japanese", Ingredients = "Ramen noodles, Miso paste, Pork broth, Chashu pork, Soft-boiled egg, Green onions, Corn, Butter", Steps = "1. Prepare pork broth (or use quality store-bought).\n2. Whisk miso paste into hot broth.\n3. Cook ramen noodles per package.\n4. Slice chashu pork.\n5. Assemble: noodles, broth, toppings.\n6. Finish with butter and green onions." },
        new Recipe { Id = 8, Title = "Teriyaki Salmon", Category = "Japanese", Ingredients = "Salmon fillets, Soy sauce, Mirin, Sake, Sugar, Ginger, Steamed rice, Sesame seeds", Steps = "1. Mix soy sauce, mirin, sake, and sugar.\n2. Sear salmon skin-side down 4 minutes.\n3. Flip and cook 2 more minutes.\n4. Pour teriyaki sauce into pan.\n5. Baste salmon until glazed.\n6. Serve over rice with sesame seeds." },
    };

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRating += stars;
            recipe.RatingCount++;
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps
        });
    }
}

@using RecipeShare.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              title="Rate @star star(s)">
            ★
        </span>
    }
    @if (_rated)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
    <span class="rating-info">(@Recipe.RatingCount ratings, avg @Recipe.AverageRating.ToString("F1"))</span>
</div>

@code {
    [Parameter, EditorRequired]
    public Models.Recipe Recipe { get; set; } = default!;

    private int _selectedRating;
    private bool _rated;

    private void Rate(int stars)
    {
        if (_rated) return;
        _selectedRating = stars;
        _rated = true;
        RecipeService.AddRating(Recipe.Id, stars);
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    margin: 1rem 0;
}

.star {
    font-size: 1.75rem;
    color: #ccc;
    cursor: pointer;
    transition: color 0.15s;
}

.star:hover,
.star.filled {
    color: #f5a623;
}

.rating-thanks {
    margin-left: 0.75rem;
    color: #28a745;
    font-weight: 500;
}

.rating-info {
    margin-left: 0.5rem;
    color: #666;
    font-size: 0.875rem;
}

